import { CommonModule, DatePipe } from '@angular/common';
import { AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnDestroy, Output, computed } from '@angular/core';
import { AvatarComponent } from '../avatar/avatar.component';
import { ButtonComponent } from '../button/button.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { ScrollingModule } from '@angular/cdk/scrolling';
import { UserCaseData } from '../../../userpanel/interfaces/userdashboard.interface';
import { IconComponent } from '../icon/icon.component';

import { RolepermitService } from '../../../core/services/permission/rolepermit.service';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { MatMenuModule } from '@angular/material/menu';
import { Router, RouterLink } from '@angular/router';
import { UserPermissionService } from '../../services/user-permission/user-permission.service';
import { UserDetail } from '../../../core/interfaces/login.interface';
import { SocketService } from '../../../core/services/socket/socket.service';
import { presentEvents } from '../../../presentation/interfaces/present.tool.interface';
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';
import { PRESENTATION_STATUS_TYPES, NOTIFICATION_TYPES, PRESENTATION_EVENTS, CASE_STATUS_CONDITIONS, CASECARD_ACTIONS, BUTTON_ACTIONS, CASECARD_ROUTES } from '../../../userpanel/utility/user-panel-constants';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'casecard',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CommonModule, AvatarComponent, ButtonComponent, MatTooltipModule, ScrollingModule, IconComponent, MatMenuModule, RouterLink, TranslateModule],
  providers: [DatePipe],
  templateUrl: './casecard.component.html',
  styleUrl: './casecard.component.scss'
})
export class CasecardComponent implements AfterViewInit, OnDestroy {
  // Constants
  readonly presentationStatusTypes = PRESENTATION_STATUS_TYPES;
  readonly notificationTypes = NOTIFICATION_TYPES;
  readonly presentationEvents = PRESENTATION_EVENTS;
  readonly caseCardActions = CASECARD_ACTIONS;
  readonly buttonActions = BUTTON_ACTIONS;
  readonly caseCardRoutes = CASECARD_ROUTES;

  // Inputs
  @Input() ticketOpen: boolean = false;
  @Input() detail: UserCaseData;
  @Input() isAdmin: boolean = false;
  @Input() ticketCount: number = 0;
  @Input() sessionId: string = null;
  @Input() isArchive: boolean;

  // Outputs
  @Output() caseChange: EventEmitter<string> = new EventEmitter();

  // State
  myRoleId: number = 0;
  isCaseAdmin: boolean = false;
  isCanPresent: boolean = false;
  userId: string;
  isCanRealtime: boolean = false;
  isCanView: boolean = false;
  userDetail: UserDetail;
  presentationStatus: boolean = false;

  // Subscriptions
  private readonly destroy$ = new Subject<void>();

  // Computed properties
  formattedUpdateDate = computed(() => {
    if (!this.detail?.dUpdateDt) {
      return '';
    }
    return new DatePipe('en-US').transform(this.detail.dUpdateDt, 'dd/MM/yyyy') || '';
  });

  constructor(
    private readonly rolePermit: RolepermitService,
    private readonly secureStorage: SecureStorageService,
    private readonly commonFunction: CommonfunctionService,
    private readonly changeDetector: ChangeDetectorRef,
    private readonly router: Router,
    private readonly userPermission: UserPermissionService,
    private readonly socket: SocketService
  ) {
    this.setupSocketSubscriptions();
  }

  private setupSocketSubscriptions(): void {
    this.socket.getUserNotifications()
      .pipe(takeUntil(this.destroy$))
      .subscribe((res: any) => this.handleUserNotification(res));

    this.socket.getPresentationTools()
      .pipe(takeUntil(this.destroy$))
      .subscribe((res: presentEvents) => this.handlePresentationEvent(res));
  }

  private handleUserNotification(res: any): void {
    try {
      if (!res?.nCaseid || this.detail?.nCaseid !== res.nCaseid) {
        return;
      }

      if (this.presentationStatusTypes.includes(res.cType)) {
        this.presentationStatus = true;
      } else if (!this.notificationTypes.includes(res.cType)) {
        return;
      }

      this.changeDetector.detectChanges();
    } catch (error) {
      throw new Error(`Error handling user notification: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  private handlePresentationEvent(res: presentEvents): void {
    if (!this.presentationEvents.includes(res?.event)) {
      return;
    }

    const shouldClearStatus = (res.event === CASE_STATUS_CONDITIONS.EVENT_USER_MANAGE && res?.data?.cStatus === CASE_STATUS_CONDITIONS.STATUS_ACTIVE && res?.data?.cPermission === CASE_STATUS_CONDITIONS.PERMISSION_DENY) || res.event === CASE_STATUS_CONDITIONS.EVENT_END;
    if (shouldClearStatus) {
      this.presentationStatus = false;
      this.changeDetector.detectChanges();
    }
  }

  ngAfterViewInit(): void {
    this.initializeComponent();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private async initializeComponent(): Promise<void> {
    try {
      this.userDetail = await this.secureStorage.getUserInfo();
      await this.initializePermissions();
      this.changeDetector.detectChanges();
    } catch (error) {
      throw new Error(`Error initializing casecard component: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  private async initializePermissions(): Promise<void> {
    if (!this.isAdmin) {
      this.userId = await this.secureStorage.getUserId();
      this.myRoleId = await this.commonFunction.fetchRoleid(this.detail.teams, this.userId);
      this.isCaseAdmin = this.rolePermit.isAdmin(this.myRoleId);
    }

    const isAdmin = this.userDetail?.isAdmin || false;
    this.isCanPresent = isAdmin || this.rolePermit.isCanPresent(this.myRoleId, this.detail.jPermission);
    this.isCanRealtime = isAdmin || this.rolePermit.isHaveRealtime(this.detail.jPermission);
    this.isCanView = isAdmin || this.rolePermit.isHaveView(this.detail.jPermission);
  }

  // Keyboard event handlers
  onTicketKeyDown(event: KeyboardEvent): void {
    if (this.isKeyboardTrigger(event)) {
      event.preventDefault();
      this.viewTicket();
    }
  }

  onButtonKeyDown(event: KeyboardEvent, action: string): void {
    if (this.isKeyboardTrigger(event)) {
      event.preventDefault();
      this.executeButtonAction(action, event);
    }
  }

  // Navigation and emission methods
  viewTicket(): void {
    this.caseChange.emit(CASECARD_ACTIONS.VIEW_TICKET);
  }

  editCase(): void {
    this.caseChange.emit(CASECARD_ACTIONS.EDIT);
  }

  goToCase(): void {
    this.navigateToCase();
  }

  goToAdmin(): void {
    try {
      if (!this.detail?.nCaseid) {
        throw new Error('Case ID is not available');
      }
      this.commonFunction.goto(CASECARD_ROUTES.CASE_BUILDER, { id: this.detail.nCaseid });
    } catch (error) {
      throw new Error(`Error navigating to admin: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  goToPresentation(): void {
    this.openPresentationWindow();
  }

  goToBundleManage(): void {
    try {
      if (!this.detail?.nCaseid) {
        throw new Error('Case ID is not available');
      }
      this.commonFunction.goto(CASECARD_ROUTES.BUNDLE_MANAGEMENT, { id: this.detail.nCaseid });
    } catch (error) {
      throw new Error(`Error navigating to bundle management: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  goToRealtimeLog(): void {
    try {
      if (!this.detail?.nCaseid) {
        throw new Error('Case ID is not available');
      }
      this.commonFunction.goto(CASECARD_ROUTES.REALTIME_LOG, { id: this.detail.nCaseid });
    } catch (error) {
      throw new Error(`Error navigating to realtime log: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  updateArchiveStatus(): void {
    try {
      const archiveAction = this.isArchive ? CASECARD_ACTIONS.ARCHIVE_FALSE : CASECARD_ACTIONS.ARCHIVE_TRUE;
      this.caseChange.emit(archiveAction);
    } catch (error) {
      throw new Error(`Error updating archive status: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  // Helper methods
  private isKeyboardTrigger(event: KeyboardEvent): boolean {
    return event.key === 'Enter' || event.key === ' ';
  }

  private executeButtonAction(action: string, event: KeyboardEvent): void {
    try {
      const actionMap: { [key: string]: () => void } = {
        [BUTTON_ACTIONS.GO_TO_CASE]: () => this.goToCase(),
        [BUTTON_ACTIONS.GO_TO_ADMIN]: () => this.goToAdmin(),
        [BUTTON_ACTIONS.GO_TO_PRESENTATION]: () => this.goToPresentation(),
        [BUTTON_ACTIONS.EDIT_CASE]: () => this.editCase(),
        [BUTTON_ACTIONS.GO_TO_BUNDLE_MANAGE]: () => this.goToBundleManage(),
        [BUTTON_ACTIONS.GO_TO_REALTIME_LOG]: () => this.goToRealtimeLog(),
        [BUTTON_ACTIONS.TOGGLE_ARCHIVE_MENU]: () => this.handleArchiveMenuToggle(event),
        [BUTTON_ACTIONS.UPDATE_ARCHIVE_STATUS]: () => this.updateArchiveStatus(),
        [BUTTON_ACTIONS.CLOSE_MENU]: () => this.handleCloseMenu(event)
      };

      const handler = actionMap[action];
      if (!handler) {
        throw new Error(`Unknown action: ${action}`);
      }
      handler();
    } catch (error) {
      throw new Error(`Error executing button action '${action}': ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  private navigateToCase(): void {
    this.performNavigation();
  }

  private async performNavigation(): Promise<void> {
    try {
      await this.userPermission.userPermissionList(this.detail.nCaseid);
      this.commonFunction.goto(CASECARD_ROUTES.MY_FILES, { id: this.detail.nCaseid });
    } catch (error) {
      throw new Error(`Error navigating to case: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  private openPresentationWindow(): void {
    try {
      const presentData = { id: this.detail.nCaseid };
      const url = this.router.serializeUrl(
        this.router.createUrlTree([CASECARD_ROUTES.PRESENTATION, JSON.stringify(presentData)])
      );
      globalThis.open(url, '_blank');
    } catch (error) {
      throw new Error(`Error opening presentation window: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  private handleArchiveMenuToggle(event: KeyboardEvent): void {
    const menuTrigger = (event.target as HTMLElement).closest('[matMenuTriggerFor]');
    if (menuTrigger) {
      (menuTrigger as any).click();
    }
  }

  private handleCloseMenu(event: KeyboardEvent): void {
    const menu = (event.target as HTMLElement).closest('mat-menu');
    if (menu) {
      (menu as any).closed.emit();
    }
  }

  // Track by functions
  trackByTeam(index: number, team: any): string {
    return team.nTeamid;
  }

  trackByUser(index: number, user: any): string {
    return user.nUserid;
  }
}